function qCoordinate(text){const m=String(text).trim().match(/^(\d{2})(\d{2})([NS])(\d{3})(\d{2})([EW])$/);if(!m||+m[2]>=60||+m[5]>=60)return null;const lat=(+m[1]+m[2]/60)*(m[3]==='S'?-1:1),lon=(+m[4]+m[5]/60)*(m[6]==='W'?-1:1);return Math.abs(lat)<=90&&Math.abs(lon)<=180?{lat,lon}:null;}
